DEFAULT = _CxxDefault()


def fill_defaults(value, default):
    """Replace the DEFAULT members of the dataclass value with those of default(),
    which is only called if there is one."""
    defaults = None
    for name in value.__dataclass_fields__:
        if getattr(value, name) is DEFAULT:
            if defaults is None:
                defaults = default()
            setattr(value, name, getattr(defaults, name))


